import { groupOffers } from "@/domain/group-offers";
import { MOCK_TRIGGERS, mockMovieById, mockSearch, toSearchKey } from "./mock-catalog";
import { DataSourceError, type DataSource } from "./types";

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * In-memory stand-in for the real data source, with movies generated by Faker (./mock-catalog).
 * The first lookup waits `latencyMs` and reports `cached: false`; repeats are instant and
 * `cached: true`, so the Discovery reveal and the Ignite snap can both be exercised.
 *
 * Special searches: "404" returns no results, "500" fails like a server bug.
 */
export function createMockDataSource({ latencyMs = 700 } = {}): DataSource {
  const seen = new Map<string, string>(); // key -> checkedAt

  async function lookup<T>(key: string, produce: () => T) {
    const previousCheck = seen.get(key);
    if (previousCheck !== undefined) {
      return { data: produce(), cached: true, checkedAt: previousCheck };
    }

    await sleep(latencyMs);
    const checkedAt = new Date().toISOString();
    seen.set(key, checkedAt);
    return { data: produce(), cached: false, checkedAt };
  }

  return {
    async search(query) {
      const searchKey = toSearchKey(query);

      if (searchKey === MOCK_TRIGGERS.serverError) {
        await sleep(latencyMs);
        // A plain Error, not a DataSourceError, so it takes the same path as a real bug.
        throw new Error("Mock server error, triggered by searching for 500.");
      }

      return lookup(`search:${searchKey}`, () => {
        if (searchKey === MOCK_TRIGGERS.noResults) {
          return [];
        }
        const entries = mockSearch(searchKey);
        return entries.map((entry) => entry.movie);
      });
    },

    async availability(movieId) {
      const entry = mockMovieById(movieId);
      if (entry === null) {
        throw new DataSourceError("not_found", "We couldn't find that movie.");
      }

      return lookup(`availability:${movieId}`, () => ({
        movie: entry.movie,
        country: "SE" as const,
        groups: groupOffers(entry.offers),
      }));
    },
  };
}
